{
  "case_id": "xsu_sg_013_specialist_declaration",
  "criteria": {
    "c01_overall_legal_correctness": {"label": "met", "reason": "Svaret gengiver korrekt, at UDK i særlige tilfælde kan bede om en speciallægeerklæring, når dokumentationen ikke tilstrækkeligt beskriver art og grad. Alle fire eksempler er med, og svaret angiver, at UDK betaler udgifterne. Det indeholder ingen af de væsentlige fejl fra rubrikken, fx at erklæring altid kræves, eller at listen er udtømmende."},
    "c02_required_elements_complete": {"label": "met", "reason": "Begge kritiske elementer er dækket: 'særlige tilfælde' og utilstrækkelig beskrivelse af art og grad, samt de fire eksempelgrupper (intensitet/hyppighed, diskrepans, behandlingsmuligheder/prognose, hverdag vs. ferie). Udgiftsdækningen er også med."},
    "c03_direct_relevance": {"label": "met", "reason": "Svaret besvarer direkte, hvornår UDK kan bede om en speciallægeerklæring."},
    "c04_source_traceability": {"label": "not_met", "reason": "Svaret angiver ingen identificerbar kilde, hverken bestemmelse eller vejledningsafsnit."},
    "c05_source_validity": {"label": "not_assessable", "reason": "Ingen kilde er angivet, så gyldigheden kan ikke vurderes."},
    "c06_claim_source_support": {"label": "not_assessable", "reason": "Ingen kilde er angivet, så støtten til påstandene kan ikke vurderes."},
    "c07_no_unsupported_legal_additions": {"label": "met", "reason": "Alle udsagn svarer til vejledningens afsnit 5.1.3.2. Der er ikke tilføjet nye regler, betingelser eller myndigheder."},
    "c08_qualifications_and_exceptions": {"label": "met", "reason": "'I særlige tilfælde' og 'kan' er bevaret. 'For eksempel' og de alternative 'eller' viser, at eksemplerne er illustrative og alternative. 'Stor tvivl' er bevaret for behandlingsmuligheder/prognose og for funktionsniveau."},
    "c09_reasoning_coherence": {"label": "met", "reason": "Svaret er sammenhængende: først hovedreglen, derefter eksempler som illustration og til sidst udgiftsdækning. Konklusionen følger af det anførte."},
    "c10_legal_modality_precision": {"label": "met", "reason": "'Kan' og 'i særlige tilfælde' gengiver kilden. Svaret gør ikke erklæringen obligatorisk og lister eksemplerne som illustrative. Formuleringen 'Udbetaling Danmark betaler udgifterne' er lidt mere absolut end 'eventuelle udgifter', men ændrer ikke betydningen."}
  },
  "xhaile_coverage": {
    "A74": {"label": "yes", "reason": "Svaret dækker, at der i særlige tilfælde kan indhentes en speciallægeerklæring, når dokumentationen ikke tilstrækkeligt beskriver art og grad, og gengiver alle fire eksempler."}
  },
  "overall_notes": "Indholdsmæssigt korrekt og fuldstændigt svar, men uden kildeangivelse. Derfor C04 not_met og C05/C06 not_assessable."
}

